<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ArrowUpRight,Bookmark,Footprints,Compass,ArrowRight,Check,ChevronRight} from 'lucide-vue-next'
import {api,dateLabel,safeUrl} from '../api'
import type {Stats,Topic} from '../types'
import {useApp} from '../stores/app'
import Notice from '../components/Notice.vue'
const app=useApp(),stats=ref<Stats|null>(null),bookmarks=ref<Topic[]>([]),loading=ref(true),error=ref(''),tab=ref('timeline'),offset=ref(0),total=ref(0),moreLoading=ref(false)
async function load(){loading.value=true;error.value='';try{const [s,b]=await Promise.all([api<Stats>('/stats'),api<{items:Topic[];total:number}>('/bookmarks?limit=20&offset=0')]);stats.value=s;bookmarks.value=b.items;total.value=b.total;offset.value=b.items.length}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function more(){moreLoading.value=true;try{const b=await api<{items:Topic[];total:number}>(`/bookmarks?limit=20&offset=${offset.value}`);bookmarks.value.push(...b.items);offset.value+=b.items.length;total.value=b.total}catch(e){app.notify(e instanceof Error?e.message:'加载失败')}finally{moreLoading.value=false}}
async function remove(topic:Topic){try{await api(`/bookmarks/${topic.id}`,{method:'DELETE'});bookmarks.value=bookmarks.value.filter(x=>x.id!==topic.id);offset.value--;total.value--;if(stats.value)stats.value.bookmark_count--;app.notify('已取消收藏')}catch(e){app.notify(e instanceof Error?e.message:'取消失败')}}
onMounted(load)
</script>
<template><div class="journey-page"><header class="page-heading"><div><p class="eyebrow">TRACES OF YOUR CURIOSITY</p><h1>我的探索<span class="serif-accent">.</span></h1><p>知识不是一张待填满的清单，而是一段逐渐延伸的旅程。</p></div><RouterLink class="button outline" to="/"><Compass :size="16"/>发现下一条线索</RouterLink></header><Notice :loading="loading" :error="error" @retry="load"/><template v-if="stats&&!loading&&!error"><section class="stats-overview"><div><span class="tiny-label">EXPLORED TOPICS</span><strong>{{stats.explored_count}}</strong><p>已探索主题<small>首次成功打开详情，按主题去重</small></p></div><div><span class="tiny-label">DISCIPLINES REACHED</span><strong>{{stats.discipline_count}}</strong><p>已接触主学科<small>按主题唯一主学科去重</small></p></div><div><span class="tiny-label">SAVED CONNECTIONS</span><strong>{{stats.bookmark_count}}</strong><p>收藏的线索<small>与熟悉程度、学习状态独立</small></p></div></section><div class="journey-layout"><section class="journey-main"><div class="section-tabs" role="group" aria-label="探索记录类型"><button @click="tab='timeline'" :class="{selected:tab==='timeline'}" :aria-pressed="tab==='timeline'"><Footprints :size="16"/>探索足迹</button><button @click="tab='bookmarks'" :class="{selected:tab==='bookmarks'}" :aria-pressed="tab==='bookmarks'"><Bookmark :size="16"/>我的收藏 <span>{{total}}</span></button></div><template v-if="tab==='timeline'"><div v-if="stats.timeline.length" class="timeline"><RouterLink v-for="(event,i) in stats.timeline" :key="`${event.topic_id}-${event.at}-${i}`" :to="`/topics/${event.topic_id}`" class="timeline-item"><span class="timeline-dot"/><span class="timeline-date">{{dateLabel(event.at)}}</span><div><span class="tiny-label">{{event.discipline_name}}</span><h3>{{event.title}}</h3><p>打开详情，认识一个新的知识入口</p></div><ArrowUpRight :size="18"/></RouterLink></div><Notice v-else empty="探索还没有开始。打开一个感兴趣或完全陌生的主题，让第一条足迹出现。"><RouterLink class="button primary" to="/">开始探索<ArrowRight :size="15"/></RouterLink></Notice><p class="privacy-note">时间线展示最近的探索记录。访问代表打开详情，不代表已经理解。</p><section v-if="stats.paths.length" class="paths-section"><div class="section-heading"><h2>跨领域探索路径</h2></div><article v-for="(path,i) in stats.paths" :key="i" class="exploration-path"><div><span>{{path.from_title}}</span><ChevronRight :size="15"/><span>{{path.to_title}}</span></div><span class="source-chip">{{path.relation_type}}</span><p>{{path.explanation}}</p><a v-if="path.source_url" :href="safeUrl(path.source_url)" target="_blank" rel="noopener noreferrer" class="text-button">查看关系依据<ArrowUpRight :size="13"/></a></article></section></template><template v-else><div v-if="bookmarks.length" class="bookmark-list"><article v-for="topic in bookmarks" :key="topic.id" class="bookmark-item"><div><span class="discipline-label" :style="{'--discipline':topic.primary_discipline.color}"><i/>{{topic.primary_discipline.name}}</span><RouterLink :to="`/topics/${topic.id}`"><h3>{{topic.title}}<ArrowUpRight :size="16"/></h3></RouterLink><p>{{topic.summary||topic.original_summary}}</p><span v-if="topic.state.explored" class="visited-label"><Check :size="12"/>已探索</span></div><button class="icon-button bookmarked" aria-label="取消收藏" @click="remove(topic)"><Bookmark :size="18" fill="currentColor"/></button></article></div><Notice v-else empty="还没有收藏的线索。在主题卡片或详情页点击书签，把想继续了解的知识留下。"/><button v-if="offset<total" class="button outline" :disabled="moreLoading" @click="more">{{moreLoading?'正在加载…':'加载更多收藏'}}</button></template></section><aside class="journey-aside"><section class="aside-panel"><span class="tiny-label">LAST 30 DAYS</span><h2>好奇心的方向</h2><p class="muted">最近 30 天已探索主题，按唯一主学科分布。</p><div v-if="stats.distribution.length" class="distribution"><div v-for="d in stats.distribution" :key="d.id"><div><span><i :style="{background:d.color}"/>{{d.name}}</span><strong>{{d.count}}</strong></div><div class="bar-track"><i :style="{background:d.color,width:`${100*(d.count||0)/Math.max(1,...stats.distribution.map(x=>x.count||0))}%`}"/></div></div></div><p v-else class="muted">最近 30 天暂无探索记录。</p></section><section v-if="stats.new_disciplines.length" class="aside-panel"><span class="tiny-label">NEW TERRITORIES</span><h2>最近抵达的新领域</h2><div class="new-disciplines"><span v-for="d in stats.new_disciplines" :key="d.id"><i :style="{background:d.color}"/>{{d.name}}<small v-if="d.first_explored_at">{{dateLabel(d.first_explored_at)}}</small></span></div></section><section class="aside-panel unexplored-panel"><span class="tiny-label">BEYOND THE FAMILIAR</span><h2>尚未踏足的地方</h2><p class="muted">仅针对当前知识库中尚未探索的主学科。</p><div class="discipline-options"><RouterLink v-for="d in stats.unexplored_disciplines" :key="d.id" :to="`/map?discipline=${d.id}`" class="option-pill"><i :style="{background:d.color}"/>{{d.name}}</RouterLink></div><p v-if="!stats.unexplored_disciplines.length" class="muted">你已接触知识库中的所有主学科，仍有很多主题等待探索。</p></section><section v-if="stats.long_unexplored_disciplines?.length" class="aside-panel"><span class="tiny-label">RETURN TO A TERRITORY</span><h2>很久没有重访的领域</h2><p class="muted">当前知识库中，超过 30 天未访问的已探索学科。</p><div class="new-disciplines"><RouterLink v-for="d in stats.long_unexplored_disciplines" :key="d.id" :to="`/map?discipline=${d.id}`"><span>{{d.name}}</span><small>最近 {{dateLabel(d.last_explored_at)}}</small></RouterLink></div></section></aside></div><details class="stats-definitions"><summary>这些数字如何计算？</summary><p v-for="(value,name) in stats.definitions" :key="name"><strong>{{name}}：</strong>{{value}}</p><p>所有记录仅属于当前匿名档案。这里不展示知识掌握百分比。</p></details></template></div></template>
